<main class="write-main"><header class="writer-head"><div><span class="writer-kicker">Change the plan, keep everyone informed</span><h1>Change booking date & time</h1><p><?=e($b['first'].' '.$b['last'])?> · <?=e($cfg['types'][$b['type']]['name'])?></p></div><a class="wbtn" href="<?=url('/write/booking-review?id='.$b['id'])?>">Back to booking</a></header><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<section class="program-card"><p>Current: <?=e((new DateTimeImmutable('@'.$b['start']))->setTimezone(comm_zone($cfg['timezone']))->format('l j F Y · H:i T'))?> · <?=(int)$cfg['types'][$b['type']]['minutes']?> minutes</p><form method="get"><input type="hidden" name="id" value="<?=e($b['id'])?>"><label>New date · <?=e($cfg['timezone'])?><input type="date" name="date" required value="<?=e($date)?>"></label><button class="wbtn">Check available times</button></form>
<?php if($slots):?><form method="post"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$b['version']?>"><fieldset><legend>Verified available start times · <?=e($cfg['timezone'])?></legend><div class="booking-slots"><?php foreach($slots as$slot):if($slot===$b['start'])continue;?><label><input type="radio" name="slot" value="<?=$slot?>" required><?=e((new DateTimeImmutable('@'.$slot))->setTimezone(comm_zone($cfg['timezone']))->format('D j M · H:i'))?></label><?php endforeach;?></div></fieldset><label>Reason for the change<textarea name="reason" maxlength="1000" required></textarea></label><label><input type="checkbox" name="confirm_change" value="1" required>Change to this date and time and notify the visitor. Existing confirmation status and sender mailbox are retained.</label><button class="wbtn primary">Confirm date & time change</button></form><?php else:?><p>No verified times available for this date. Select another date. The existing booking stays in place.</p><?php endif;?></section></main><link rel="stylesheet" href="<?=asset('css/program.css')?>"><link rel="stylesheet" href="<?=asset('css/communication.css')?>">
